This improved version adopts Relative Cursor Movement, avoiding the \E[6n coordinate queries that are vulnerable to terminal scrolling. It is much more stable and compatible with major terminal environments (macOS Terminal, Windows Terminal, iTerm2, Linux Console). #!/usr/bin/env bash # ============================================================================== # Interactive Arrow Key Menu Function # Arguments: List of options (strings or array expansion) # Returns: Index value of the option selected by the user (0, 1, 2...) # ============================================================================== select_option() { local -a options=("$@") local num_options=${#options[@]} # Return error directly if no options are passed [[ $num_options -eq 0 ]] && return 1 # ANSI control code definitions local ESC=$'\033' local CURSOR_OFF="${ESC}[?25l" local CURSOR_ON="${ESC}[?25h" local CLEAR_LINE="${ESC}[2K" local TEXT_INVERT="${ESC}[7m" local TEXT_RESET="${ESC}[0m" # Trap interrupt signals (Ctrl+C) to ensure terminal cursor and attributes are properly restored trap 'printf "${CURSOR_ON}"; stty echo; printf "
"; exit 130' INT TERM # Disable cursor blinking printf "%s" "${CURSOR_OFF}" local selected=0 # Initial render of the list local i for ((i=0; i<num_options; i++)); do if [[ $i -eq $selected ]]; then printf " ${TEXT_INVERT} > %s ${TEXT_RESET}
" "${options[i]}" else printf " %s 
" "${options[i]}" fi done # Keyboard input listening loop while true; do # Read 3 characters to capture arrow key escape sequences (\033[A, \033[B) IFS= read -rsn1 key if [[ $key == "${ESC}" ]]; then read -rsn2 -t 0.1 rest key="${key}${rest}" fi case "$key" in "${ESC}[A"|k|K) # Up arrow (or Vim key 'k') ((selected--)) [[ $selected -lt 0 ]] && selected=$((num_options - 1)) ;; "${ESC}[B"|j|J) # Down arrow (or Vim key 'j') ((selected++)) [[ $selected -ge $num_options ]] && selected=0 ;; "") # Enter key to confirm selection break ;; esac # Move cursor back up to the start of the list and overwrite the entire menu printf "${ESC}[%dA" "${num_options}" for ((i=0; i<num_options; i++)); do printf "${CLEAR_LINE}" if [[ $i -eq $selected ]]; then printf " ${TEXT_INVERT} > %s ${TEXT_RESET}
" "${options[i]}" else printf " %s 
" "${options[i]}" fi done done # Restore cursor and environment printf "%s" "${CURSOR_ON}" # Output the selected index value echo "$selected" }
